\documentclass{article}
% Portrait A0: 841mm x 1189mm
\usepackage[paperwidth=841mm,paperheight=1189mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\usepackage{microtype}
\pagestyle{empty}

% ── Color Palette: Deep Warm Tones (Oranges, Reds, Earthy Golds) ──
\definecolor{primary}{HTML}{7B1A00}      % deep burnt red
\definecolor{secondary}{HTML}{C0390A}    % warm red-orange
\definecolor{accent}{HTML}{D4820C}       % earthy gold
\definecolor{accentlight}{HTML}{F0A830}  % bright gold
\definecolor{bgposter}{HTML}{1A0D08}     % very dark warm brown/black
\definecolor{bgsection}{HTML}{2A1208}    % slightly lighter dark bg

% Card backgrounds (warm tinted, not white)
\definecolor{redbg}{HTML}{2E100A}        % dark warm red tint
\definecolor{goldbg}{HTML}{261A06}       % dark gold tint
\definecolor{darkcardbg}{HTML}{221008}   % darkest card bg
\definecolor{statbg}{HTML}{3D1A09}       % stat banner background

% Text
\definecolor{textwhite}{HTML}{F5EDE8}    % warm white
\definecolor{textlight}{HTML}{D4B8A8}    % muted warm text
\definecolor{textyellow}{HTML}{F0C060}   % highlight text

% Highlight backgrounds for stat boxes
\definecolor{stathighlight}{HTML}{4D2010}
\definecolor{goldhighlight}{HTML}{3A2806}

\pagecolor{bgposter}
\color{textwhite}

% ── List styling ──
\setlist[itemize]{leftmargin=28pt, itemsep=8pt, parsep=2pt, topsep=4pt,
  label={\color{accent}$\blacktriangleright$}}
\setlist[enumerate]{leftmargin=28pt, itemsep=10pt, parsep=2pt, topsep=4pt,
  label={\color{accentlight}\bfseries\arabic*.}}

% ── Card styles ──
\tcbset{
  % Deep red accent card
  redcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=redbg,
    borderline west={6pt}{0pt}{secondary},
    left=18pt, right=16pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{secondary},
    coltitle=secondary, colbacktitle=redbg!80!black,
    toptitle=8pt, bottomtitle=8pt,
    titlerule=1.5pt, titlerule style={secondary!40},
    valign=top, drop shadow={opacity=0.25},
  },
  % Gold accent card
  goldcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=goldbg,
    borderline west={6pt}{0pt}{accent},
    left=18pt, right=16pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{accentlight},
    coltitle=accentlight, colbacktitle=goldbg!80!black,
    toptitle=8pt, bottomtitle=8pt,
    titlerule=1.5pt, titlerule style={accent!40},
    valign=top, drop shadow={opacity=0.25},
  },
  % Dark primary card
  darkcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=darkcardbg,
    borderline west={6pt}{0pt}{primary},
    left=18pt, right=16pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{secondary},
    coltitle=secondary, colbacktitle=darkcardbg,
    toptitle=8pt, bottomtitle=8pt,
    titlerule=1.5pt, titlerule style={primary!60},
    valign=top, drop shadow={opacity=0.25},
  },
  % Highlight / CTA card
  highlightcard/.style={
    enhanced, arc=0pt, boxrule=2pt, colframe=accent, colback=goldhighlight,
    borderline west={8pt}{0pt}{accentlight},
    left=18pt, right=16pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{42}{50}\selectfont\bfseries\color{bgposter},
    coltitle=bgposter, colbacktitle=accent,
    toptitle=8pt, bottomtitle=8pt,
    valign=top, drop shadow={opacity=0.30},
  },
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=3, rows=20, spacing=0mm},
]

%% ══════════════════════════════════════════════
%% TITLE BAR  (rows 1-4, all 3 columns)
%% ══════════════════════════════════════════════
\posterbox[
  enhanced,
  colback=primary,
  colframe=primary,
  arc=0pt, boxrule=0pt,
  left=36pt, right=36pt, top=14pt, bottom=12pt,
  halign=center, valign=center,
  interior style={
    left color=primary!90!black,
    right color=secondary!60!primary
  },
  drop shadow={opacity=0.35}
]{name=title, column=1, span=3, between=top and row4}{
  {\fontsize{32}{40}\selectfont\bfseries\color{accent} FEEDING AMERICA}\\[10pt]
  {\fontsize{76}{88}\selectfont\bfseries\color{textwhite}
    Hunger Doesn't Wait}\\[4pt]
  {\fontsize{76}{88}\selectfont\bfseries\color{textyellow}
    Together We Can End It}\\[16pt]
  {\fontsize{36}{44}\selectfont\color{textlight}
    48 million Americans face hunger. Billions of meals are being delivered.\\
    \textbf{\color{textwhite}Your action makes the difference.}}
}

%% ══════════════════════════════════════════════
%% STAT BANNER  (rows 4-7, all 3 columns)
%% ══════════════════════════════════════════════
\posterbox[
  enhanced,
  colback=statbg,
  colframe=statbg,
  arc=0pt, boxrule=0pt,
  left=10pt, right=10pt, top=10pt, bottom=10pt,
  borderline south={3pt}{0pt}{accent!50},
  valign=center,
]{name=stats, column=1, span=3, between=row4 and row7}{
  \centering
  %% Stat 1 — 48 million
  \begin{minipage}[c]{0.305\linewidth}\centering
    \fcolorbox{secondary!60}{stathighlight}{\parbox{0.90\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{70}{82}\selectfont\bfseries\color{secondary} 48M}\\[4pt]
      {\fontsize{28}{34}\selectfont\bfseries\color{textwhite} Americans}\\[2pt]
      {\fontsize{24}{30}\selectfont\color{textlight} face hunger today}%
      \vspace{8pt}%
    }}
  \end{minipage}\hfill
  %% Stat 2 — 5.7 billion meals
  \begin{minipage}[c]{0.355\linewidth}\centering
    \fcolorbox{accentlight!70}{goldhighlight}{\parbox{0.90\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{70}{82}\selectfont\bfseries\color{accentlight} 5.7B}\\[4pt]
      {\fontsize{28}{34}\selectfont\bfseries\color{textwhite} Meals Distributed}\\[2pt]
      {\fontsize{24}{30}\selectfont\color{textlight} and counting}%
      \vspace{8pt}%
    }}
  \end{minipage}\hfill
  %% Stat 3 — 14 million children
  \begin{minipage}[c]{0.305\linewidth}\centering
    \fcolorbox{secondary!60}{stathighlight}{\parbox{0.90\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{70}{82}\selectfont\bfseries\color{secondary} 14M}\\[4pt]
      {\fontsize{28}{34}\selectfont\bfseries\color{textwhite} Children}\\[2pt]
      {\fontsize{24}{30}\selectfont\color{textlight} go hungry in the U.S.}%
      \vspace{8pt}%
    }}
  \end{minipage}
}

%% ══════════════════════════════════════════════
%% ROW A: Crisis  |  Impact  |  Community
%% rows 7–12
%% ══════════════════════════════════════════════

%% Col 1 — Crisis Overview
\posterbox[redcard, title={The Hunger Crisis}
]{name=crisis, column=1, between=row7 and row12}{
  \fontsize{32}{42}\selectfont\color{textwhite}
  \begin{itemize}
    \item Hunger exists in \textbf{\color{textyellow}every U.S. community}
    \item Urban \& rural families struggle to afford \textbf{nutritious food}
    \item Every zip code — neighbors, classmates, coworkers in need
    \item Food insecurity spikes after job loss, illness, \& inflation
  \end{itemize}
  \vspace{10pt}
  \colorbox{stathighlight}{\parbox{0.92\linewidth}{%
    \fontsize{30}{38}\selectfont\centering\vspace{4pt}
    \textbf{\color{accentlight} 4.3 billion pounds} of good food rescued\\
    from waste — and delivered to neighbors
    \vspace{4pt}%
  }}
}

%% Col 2 — Collective Impact (key metric showcase)
\posterbox[goldcard, title={Our Collective Impact}
]{name=impact, column=2, between=row7 and row12}{
  \fontsize{32}{42}\selectfont\color{textwhite}
  \begin{itemize}
    \item \textbf{\color{accentlight}200+} food banks across all 50 states \& Puerto Rico
    \item \textbf{\color{accentlight}60,000+} free food distribution programs
    \item Rescued food that would otherwise go to \textbf{waste}
    \item System moves food \textbf{quickly, safely, reliably}
  \end{itemize}
  \vspace{10pt}
  \colorbox{goldhighlight}{\parbox{0.92\linewidth}{%
    \fontsize{30}{38}\selectfont\centering\vspace{4pt}
    \textbf{\color{textyellow} \$1 donated = 10 meals} provided\\
    to neighbors in need — matched for limited time
    \vspace{4pt}%
  }}
}

%% Col 3 — Community Voice
\posterbox[darkcard, title={Community in Action}
]{name=community, column=3, between=row7 and row12}{
  \fontsize{32}{42}\selectfont\color{textwhite}
  \begin{itemize}
    \item \textbf{Local wisdom} drives national action every day
    \item Food bank leaders are \textbf{passionate community members}
    \item Neighbors' voices \textbf{\color{textyellow}shape real solutions}
    \item Research-driven: stories guide policy \& programs
  \end{itemize}
  \vspace{10pt}
  \colorbox{redbg!120!black}{\parbox{0.92\linewidth}{%
    \fontsize{27}{35}\selectfont\color{textlight}\vspace{4pt}
    \textit{"I have high blood pressure and am on a budget. They give you groceries and recipes. I've learned how to use whole foods."}\\[4pt]
    \fontsize{25}{32}\selectfont\textbf{\color{accent}— Kaycee, Washington}
    \vspace{4pt}%
  }}
}

%% ══════════════════════════════════════════════
%% ROW B: Pillars  |  $1=10meals HERO  |  Vision
%% rows 12–17
%% ══════════════════════════════════════════════

%% Col 1 — Four Pillars
\posterbox[goldcard, title={How We Unite Communities}
]{name=pillars, column=1, between=row12 and row17}{
  \fontsize{32}{42}\selectfont\color{textwhite}
  \begin{enumerate}
    \item \textbf{\color{accentlight}Research-Driven} — neighbors' stories shape solutions
    \item \textbf{\color{accentlight}Local + National} — community wisdom, nationwide reach
    \item \textbf{\color{accentlight}Nationwide Scale} — food moves fast to those who need it
    \item \textbf{\color{accentlight}Nutrition for All} — healthier food, fuller lives
  \end{enumerate}
}

%% Col 2 — Dollar Impact HERO
\posterbox[
  enhanced, arc=0pt, boxrule=0pt,
  colback=secondary!80!black,
  borderline west={8pt}{0pt}{accentlight},
  interior style={left color=secondary!90!black, right color=primary!80!black},
  left=20pt, right=18pt, top=10pt, bottom=10pt,
  fonttitle=\fontsize{40}{48}\selectfont\bfseries\color{textwhite},
  coltitle=textwhite, colbacktitle=primary,
  toptitle=10pt, bottomtitle=8pt,
  titlerule=2pt, titlerule style={accentlight!60},
  valign=center,
  drop shadow={opacity=0.35},
  title={Your Dollar, Multiplied}
]{name=dollar, column=2, between=row12 and row17}{
  \centering\vspace{6pt}
  {\fontsize{110}{120}\selectfont\bfseries\color{accentlight} \$1}\\[-4pt]
  {\fontsize{50}{58}\selectfont\bfseries\color{textwhite} =}\\[-4pt]
  {\fontsize{110}{120}\selectfont\bfseries\color{textyellow} 10}\\[4pt]
  {\fontsize{40}{48}\selectfont\bfseries\color{textwhite} MEALS}\\[8pt]
  {\fontsize{28}{36}\selectfont\color{textlight}
    Every dollar donated provides\\
    \textbf{\color{accentlight}at least 10 meals} to a neighbor in need.\\[6pt]
    Gifts are matched for a limited time\\
    to move \textbf{fresh food faster}.}
  \vspace{6pt}
}

%% Col 3 — Vision
\posterbox[redcard, title={A Future Without Hunger}
]{name=vision, column=3, between=row12 and row17}{
  \fontsize{32}{42}\selectfont\color{textwhite}
  \begin{itemize}
    \item Hunger touches \textbf{every U.S. community} — not one is immune
    \item Food rescue \textbf{cannot wait} — every day matters
    \item United communities \textbf{\color{textyellow}end hunger together}
    \item The resolve to end hunger is \textbf{stronger than ever}
  \end{itemize}
  \vspace{10pt}
  \colorbox{stathighlight}{\parbox{0.92\linewidth}{%
    \fontsize{30}{38}\selectfont\centering\vspace{4pt}
    \textbf{\color{textwhite}An America without hunger}\\
    {\color{textlight}is within reach — when we act together}
    \vspace{4pt}%
  }}
}

%% ══════════════════════════════════════════════
%% ROW C: CALLS TO ACTION — full width
%% rows 17–20
%% ══════════════════════════════════════════════
\posterbox[
  enhanced, arc=0pt, boxrule=0pt,
  colback=goldhighlight,
  borderline west={8pt}{0pt}{accentlight},
  borderline north={3pt}{0pt}{accent!60},
  interior style={left color=goldhighlight, right color=goldhighlight!70!black},
  left=20pt, right=20pt, top=10pt, bottom=12pt,
  fonttitle=\fontsize{48}{56}\selectfont\bfseries\color{bgposter},
  coltitle=bgposter, colbacktitle=accentlight,
  toptitle=10pt, bottomtitle=8pt,
  titlerule=2pt, titlerule style={accent!60},
  drop shadow={opacity=0.30},
  title={Take Action — Every Step Ends Hunger}
]{name=cta, column=1, span=3, between=row17 and bottom}{
  \fontsize{32}{42}\selectfont\color{textwhite}
  \begin{minipage}[t]{0.235\linewidth}
    \centering
    {\fontsize{52}{60}\selectfont\color{accentlight}$\heartsuit$}\\[4pt]
    {\fontsize{38}{46}\selectfont\bfseries\color{textyellow} DONATE}\\[6pt]
    {\fontsize{30}{38}\selectfont\color{textlight}
      \$1 = 10 meals.\\
      Every gift matched\\
      for limited time.}
  \end{minipage}\hfill\vrule width 1pt height 180pt depth 0pt \color{accent!40}\hfill%
  \begin{minipage}[t]{0.235\linewidth}
    \centering
    {\fontsize{52}{60}\selectfont\color{accentlight}$\star$}\\[4pt]
    {\fontsize{38}{46}\selectfont\bfseries\color{textyellow} ADVOCATE}\\[6pt]
    {\fontsize{30}{38}\selectfont\color{textlight}
      Urge lawmakers\\
      to support hunger\\
      relief programs.}
  \end{minipage}\hfill\vrule width 1pt height 180pt depth 0pt \color{accent!40}\hfill%
  \begin{minipage}[t]{0.235\linewidth}
    \centering
    {\fontsize{52}{60}\selectfont\color{accentlight}$\bullet$}\\[4pt]
    {\fontsize{38}{46}\selectfont\bfseries\color{textyellow} FUNDRAISE}\\[6pt]
    {\fontsize{30}{38}\selectfont\color{textlight}
      Inspire your\\
      community to\\
      give together.}
  \end{minipage}\hfill\vrule width 1pt height 180pt depth 0pt \color{accent!40}\hfill%
  \begin{minipage}[t]{0.235\linewidth}
    \centering
    {\fontsize{52}{60}\selectfont\color{accentlight}$\clubsuit$}\\[4pt]
    {\fontsize{38}{46}\selectfont\bfseries\color{textyellow} VOLUNTEER}\\[6pt]
    {\fontsize{30}{38}\selectfont\color{textlight}
      Sort, pack \&\\
      distribute food.\\
      Many hands needed.}
  \end{minipage}
  \vspace{6pt}
  \par\noindent
  \colorbox{stathighlight!80!goldhighlight}{\parbox{0.97\linewidth}{%
    \centering\fontsize{30}{38}\selectfont\color{textwhite}\vspace{3pt}
    \textbf{feedingamerica.org} \quad|\quad Together, we've distributed \textbf{\color{textyellow}5.7 billion meals}. \quad|\quad \textbf{Hunger doesn't wait — and neither should we.}
    \vspace{3pt}%
  }}
}

\end{tcbposter}
\end{document}

